import numpy as np
from scipy import linalg

def random_array(shape):
    return np.random.rand(*shape)

def add(arr1, arr2):
    return np.add(arr1, arr2)

def subtract(arr1, arr2):
    return np.subtract(arr1, arr2)

def multiply(arr1, arr2):
    return np.dot(arr1, arr2)

def inverse(arr):
    return linalg.inv(arr)

def norm(arr, ord_type=None):
    return np.linalg.norm(arr, ord_type)

if __name__ == ""__main__"":
    while True:
        try:
            shape = tuple(map(int, input(""Enter array dimensions (comma separated): "").split(',')))
