            arr2 = random_array(shape)
            print('\nRandomly generated array 2:\n', arr2)

            print(""\nAddition of arrays:"")
            print(add(arr1, arr2))

            print(""\nSubtraction of arrays:"")
            print(subtract(arr1, arr2))

            print(""\nMultiplication of arrays:"")
            print(multiply(arr1, arr2))

            print(""\nInverse of array 1:"")
            print(inverse(arr1))

            ord_type = int(input(""Enter order type for norm (None for Frobenius): ""))
            print(f""Norm with ord={ord_type} is {norm(arr1, ord_type)}"")
        except Exception as e:
            print('Invalid input. Please try again.', str(e))
