from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.exceptions import InvalidTag
import base64
import os

class EncryptionConfig:
    def __init__(self, algorithm='AES', key_size=256, padding='PKCS#1v1_5', iv=None):
        self.algorithm = algorithm
        self.key_size = key_size
        self.padding = padding
        self.iv = iv if iv else os.urandom(16)

    def get_cipher(self, key):
        if self.algorithm == 'AES':
            return Cipher(algorithms.AES(key), modes.CBC(self.iv), backend=default_backend())
        # other algorithms here

    def padding_scheme(self):
        if self.padding == 'PKCS#1v1_5':
            return asym_padding.PKCS1v15()
        # other padding schemes here

class Encryption:
    def __init__(self, config=EncryptionConfig()):
        self.config = config

    @staticmethod
    def generate_key(length=32):
        return Fernet.generate_key()[:length]

    @staticmethod
    def validate_keys(encrypt_key, decrypt_key):
        if encrypt_key == decrypt_key:
            return True
        else:
            print(""Decryption key does not match the encrypted data's key."")
            return False

    def encrypt(self, message, key):
        cipher = self.config.get_cipher(key)
        encryptor = cipher.encryptor()
        ct = encryptor.update(message) + encryptor.finalize()
        return base64.b64encode(ct).decode('utf-8')

    def decrypt(self, message, key):
        if not self.validate_keys(encrypt_key=key, decrypt_key=key):
            raise Exception(""Invalid decryption key"")  # replace with your own exception handling mechanism

        try:
            cipher = self.config.get_cipher(key)
            decryptor = cipher.decryptor()
            message = base64.b64decode(message.encode('utf-8'))
            pt = decryptor.update(message) + decryptor.finalize()
        except InvalidTag:
            print(""Decryption failed."")  # replace with your own exception handling mechanism
            return None

        return pt
