import json

class JsonParser:
    def __init__(self):
        self.registry = {}

    def add_factory(self, id, factory_func):
        self.registry[id] = factory_func

    def create_instance_from_json(self, json_str, id):
        obj = json.loads(json_str)
        return self.registry[id](obj)

    def convert_to_json_string(self, obj):
        return json.dumps(obj)

