        self.upgrades = [
            {'name': 'Speed Boost', 'cost': 100},
            {'name': 'Damage Increase', 'cost': 150},
            {'name': 'Health Regen', 'cost': 200}
        ]
        self.last_selections = {}
        self.cooldown = 15

    def select_upgrade(self):
        current_time = time.time()

        for upgrade in self.upgrades:
            if upgrade['name'] not in self.last_selections or (current_time - self.last_selections[upgrade['name']]) > self.cooldown:
                selection_chance = random.randint(1, 3)
                if selection_chance == 1:
                    print(f'Selected: {upgrade[""name""]}')
                    self.last_selections[upgrade['name']] = current_time
                    return upgrade['cost']

        print(""No upgrades available for selection."")
        return None

