```python
class Book:
    def __init__(self, id, title, author, price):
        self.id = id
        self.title = title
        self.author = author
        self.price = price

class InventoryManagementSystem:
    def __init__(self):
        self.inventory = []

    def add_book(self, id, title, author, price):
        if any(book for book in self.inventory if book.id == id or price < 0):
            print(""Invalid ID or negative price."")
            return 
        new_book = Book(id, title, author, price)
        self.inventory.append(new_book)

    def remove_book(self, id):
        for i in range(len(self.inventory)):
            if self.inventory[i].id == id:
                del self.inventory[i]
                break 

    def display_books(self):
        for book in self.inventory:
            print(""ID: "",book.id,""Title: "",book.title,""Author: "",book.author,""Price: "",book.price)

    def search_by_title(self, title):
        return [book for book in self.inventory if book.title == title]

    def search_by_author(self, author):
        return [book for book in self.inventory if book.author == author]

    def sort_by_title(self):
        self.inventory = sorted(self.inventory, key=lambda x: x.title)

    def sort_by_price(self):
        self.inventory = sorted(self.inventory, key=lambda x: x.price)

    def total_value(self):
        return sum([book.price for book in self.inventory])
```
This code first defines a `Book` class with properties ID, title, author and price. Then, it creates an `InventoryManagementSystem` that uses this Book objects. It allows adding, removing and displaying books from the inventory, searching by title or author, sorting by title or price, and calculating the total value of all books in the inventory.
