from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import rsa
from cryptography.hazmat.backends import default_backend
import os

def generate_rsa_key_pairs(num_keys, output_format, label_ids=None):
    try:
        if num_keys > 1024 or num_keys < 1:
            raise ValueError(""The number of keys must be between 1 and 1024"")

        public_exponent = 65537
        key_size = 2048
        backend = default_backend()

        if label_ids is not None:
            if len(label_ids) != num_keys:
                raise ValueError(""The number of labels must match the number of keys"")

        public_keys, private_keys = [], []
        for i in range(num_keys):
            new_key = rsa.generate_private_key(public_exponent=public_exponent, key_size=key_size, backend=backend)

            # Generate the public and private keys
            public_pem = new_key.public_key().public_bytes(encoding=serialization.Encoding.PEM, format=serialization.PublicFormat.SubjectPublicKeyInfo)
            private_pem = new_key.private_bytes(encoding=serialization.Encoding.PEM, format=serialization.PrivateFormat.TraditionalOpenSSL, encryption_algorithm=serialization.NoEncryption())

            public_keys.append(public_pem)
            private_keys.append(private_pem)

        if output_format == ""combined"":
            keys = {}
            for i in range(num_keys):
                label = label_ids[i] if label_ids else str(i+1)  # If no labels are provided, use the key index as a label.
                keys[label] = {'public': public_keys[i], 'private': private_keys[i]}
            return keys
        elif output_format == ""public_private"":
            return (public_keys, private_keys)
    except ValueError as ve:
        print(""An error occurred while generating the RSA key pairs:"", str(ve))
    except Exception as e:
        print(""Unexpected error: "", str(e))
```
