```",338,,"['Here's the code you asked for:

```python
import random
import time

class GameUpgradeSelector:
    def __init__(self):
        self.upgrades = [
            {'name': 'Speed Boost', 'cost': 100},
            {'name': 'Damage Increase', 'cost': 150},
            {'name': 'Health Regen', 'cost': 200}
        ]
        self.last_selections = {}
        self.cooldown = 15
        self.upgrades_purchased = []

    def select_upgrade(self):
        current_time = time.time()

        for upgrade in self.upgrades:
            if upgrade['name'] not in self.last_selections or (current_time - self.last_selections[upgrade['name']]) > self.cooldown:
                selection_chance = random.randint(1, 3)
                if selection_chance == 1:
                    print(f'Selected: {upgrade[""name""]}')
                    self.last_selections[upgrade['name']] = current_time
                    return upgrade['cost'], upgrade['name']

        return None, None

player_wallet = 500
max_upgrades_allowed = 3

game_upgrader = GameUpgradeSelector()

while player_wallet > 0 and len(game_upgrader.upgrades_purchased) < max_upgrades_allowed:
    upgrade_cost, upgrade_name = game_upgrader.select_upgrade()
    if upgrade_cost is not None:
        if player_wallet >= upgrade_cost and len(game_upgrader.upgrades_purchased) < max_upgrades_allowed:
            player_wallet -= upgrade_cost
            print(f""Upgraded {upgrade_name} for {upgrade_cost} credits."")
            game_upgrader.upgrades_purchased.append({'name': upgrade_name, 'cost': upgrade_cost})
    time.sleep(2)

print(""Upgrading complete!\n\nYour upgrades:"")
for upgrade in game_upgrader.upgrades_purchased:
    print(f""Name: {upgrade['name']}, Cost: {upgrade['cost']}"")
```
