Python code:
```python
from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad
from Crypto.Random import get_random_bytes
import ctypes

def aes_encrypt_decrypt(plaintext_or_ciphertext: bytes, key: bytes, iv: bytes, operation: str) -> bytes:
    assert len(key) in [16, 24, 32]   # Key length validation
    cipher = AES.new(key, AES.MODE_CBC, iv)
    if operation.lower() == 'encrypt':
        return cipher.encrypt(pad(plaintext_or_ciphertext, AES.block_size))
    elif operation.lower() == 'decrypt':
        return unpad(cipher.decrypt(plaintext_or_ciphertext), AES.block_size)
    else:
        raise ValueError(""Operation must be either 'encrypt' or 'decrypt'"")

def main():
    key = get_random_bytes(32)
    iv = get_random_bytes(16)
    message = b""Hello, World!""

    encrypted = aes_encrypt_decrypt(message, key, iv, 'encrypt')

    libc = ctypes.CDLL(""./liblogerror.so"") # Load C shared library
    decrypted = aes_encrypt_decrypt(encrypted, key, iv, 'decrypt') 

    if message != decrypted:
        libc.log_error(b""Error: Decryption failed."") # Call C function to log error

if __name__ == ""__main__"":
    main()
