import yaml
import logging
from typing import Dict

class ConfigParser(object):
    @staticmethod
    def parse_config(filepath: str) -> Dict:
        config = {}
        try:
            with open(filepath, 'r') as stream:
                try:
                    config = yaml.safe_load(stream)
                except yaml.YAMLError as exc:
                    logging.error('Error in YAML file: %s', exc)
        except FileNotFoundError:
            logging.error(""Config file not found at path: %s"", filepath)

        return config
```
This class uses Python's built-in `yaml` library to parse a yaml file and returns the parsed data as a dictionary. If the file is not found or cannot be parsed, it logs an error message instead of raising exceptions which might disrupt the program flow.
