from typing import List, Tuple, Dict, Union
import gc

class State:
    def __init__(self, stateId: str, connections: Dict[str, Union[str, None]]):
        self.stateId = stateId
        self.connections = connections

def create_new_state(index: int, stateId: str, connections: Dict[str, Union[str, None]]) -> State:
    return State(f""{stateId}_{index}"", connections)

def manage_fsa(states_list: List[Tuple[str, Dict[str, Union[str, None]]]], fsa_ptr) -> None:
    current_index = len(fsa_ptr.states)

    for stateId, connections in states_list:
        new_state = create_new_state(current_index, stateId, connections)

        # Allocate memory and update FSA pointer
        fsa_ptr.states.append(new_state)
        current_index += 1

    gc.collect()
