```python
import argparse
import string
import random

def generate_password(length=8, uppercase=False, lowercase=False, digits=False, special_chars=False):
    password = []

    if not any((uppercase, lowercase, digits, special_chars)):
        print(""Please choose at least one character type."")
        return None

    if uppercase:
        password.append(random.choice(string.ascii_uppercase))

    if lowercase:
        password.append(random.choice(string.ascii_lowercase))

    if digits:
        password.append(random.choice(string.digits))

    if special_chars:
        password.append(random.choice(string.punctuation))

    for i in range(length - len(password)):
        choice = random.randint(0, 3)
        if uppercase and choice == 0:
            password.append(random.choice(string.ascii_uppercase))
        elif lowercase and choice == 1:
            password.append(random.choice(string.ascii_lowercase))
        elif digits and choice == 2:
            password.append(random.choice(string.digits))
        elif special_chars and choice == 3:
            password.append(random.choice(string.punctuation))

    random.shuffle(password)
    return ''.join(password)

if __name__ == ""__main__"":
    parser = argparse.ArgumentParser()
    parser.add_argument('--length', type=int, default=8, help='Password length')
    parser.add_argument('--uppercase', action=""store_true"", help='Include upper case letters')
    parser.add_argument('--lowercase', action=""store_true"", help='Include lower case letters')
    parser.add_argument('--digits', action=""store_true"", help='Include digits')
    parser.add_argument('--special-chars', action=""store_true"", help='Include special characters')

    args = parser.parse_args()

    password = generate_password(args.length, args.uppercase, args.lowercase, args.digits, args.special_chars)

    if password:
        print('Generated Password is : ', password)
```
