```python
from Crypto.Cipher import AES
from Crypto.Random import get_random_bytes
import hashlib
import os
import binascii

# dictionary to store user sessions and keys
userSessions = {}

def createSession(username):
    if username not in userSessions:
        # generating unique sessionID and keyID
        sessionID = binascii.hexlify(os.urandom(16))
        keyID = hashlib.sha256(get_random_bytes(16)).digest()
        userSessions[username] = {""sessionID"": sessionID, ""keyID"": keyID}
    else:
        print(""User already has an active session."")

def getKeyForSession(username):
    if username in userSessions:
        return userSessions[username]['keyID']
    else:
        print(""No such active session for this user"")

def encryptData(data, key):
    cipher = AES.new(key, AES.MODE_EAX)
    nonce = cipher.nonce
    ciphertext, tag = cipher.encrypt_and_digest(data)
    return (nonce, ciphertext, tag)
```

