class Book:
    def __init__(self, id, title, author, price):
        self.id = id
        self.title = title
        self.author = author
        self.price = price

class InventoryManager:
    def __init__(self):
        self.book_records = []
        self.offsets_array = [0] * 1000000   # Max book count
        self.keys_array = [None] * 1000000   # Max book count

    def add_book(self, title, author, price):
        id_available = False
        while not id_available:
            available_id = self.search_free_id()
            if available_id is not None:
                new_book = Book(available_id, title, author, price)
                self.insert_book(new_book)
                id_available = True

    def remove_book(self, book_id):
        self.remove_from_array(book_id)
        self.update_offset_values()

    def display_books(self):
        for record in self.book_records:
            print(f""ID: {record.id}, Title: {record.title}, Author: {record.author}, Price: {record.price}"")

    def search_free_id(self):
        for i in range(len(self.offsets_array)):
            if self.offsets_array[i] == 0:
                return i
        return None

    def insert_book(self, book):
        index_to_insert = self.search_free_id()
        if index_to_insert is not None:
            self.offsets_array[index_to_insert] += 1
            self.keys_array[index_to_insert] = book.id
            self.book_records.append(book)

    def remove_from_array(self, book_id):
        index_to_remove = self.keys_array.index(book_id)
        self.offsets_array[index_to_remove] -= 1

    def update_offset_values(self):
        for i in range(len(self.offsets_array)):
            if self.offsets_array[i] > 1:
                self.offsets_array[i] -= 1

# Example usage of the inventory manager system and additional data management features.
manager = InventoryManager()

# Adding books to the inventory.
manager.add_book(""The Great Gatsby"", ""F. Scott Fitzgerald"", 9.99)
manager.add_book(""To Kill a Mockingbird"", ""Harper Lee"", 7.99)

# Displaying all books in the inventory.
manager.display_books()

# Removing a book from the inventory by its ID.
manager.remove_book(2)

# Displaying the updated inventory after removal.
manager.display_books()
