import hashlib
import sys

def computeMd5(filePath):
    with open(filePath, ""rb"") as file:
        md5 = hashlib.md5()

        while chunk := file.read(8192): # read in chunks to avoid large memory usage
            md5.update(chunk)

        return md5.hexdigest()

if __name__ == ""__main__"": 
    print(computeMd5(sys.argv[1]))
