import sys
import string
import random

def generate_password(length=12, use_upper=True, use_lower=True, use_digits=True, use_special=False):
    if length < 4:
        print(""Password length must be at least 4 characters."")
        return None

    chars = ''
    if use_upper:
        chars += string.ascii_uppercase
    if use_lower:
        chars += string.ascii_lowercase
    if use_digits:
        chars += string.digits
    if use_special:
        chars += string.punctuation

    if not chars:
        print(""At least one character type must be selected."")
        return None

    password = ''.join(random.choice(chars) for _ in range(length))
    return password

def main():
    args = sys.argv[1:]

    length = int(args[0]) if args and args[0].isdigit() else 12

    try:
        include_upper = bool(args[1] == 'True')
        include_lower = bool(args[2] == 'True')
        include_digits = bool(args[3] == 'True')
        include_special = bool(args[4] == 'True')

        password = generate_password(length, include_upper, include_lower, include_digits, include_special)

        if password is not None:
            print(password)

    except IndexError:
        print(""Usage: python script.py <length> [True|False for each option]"")

if __name__ == ""__main__"":
    main()
