```python
def calculate_md5(filepath):
    with open(filepath, 'rb') as f:
        digest = hashlib.md5()

        while True:
            chunk = f.read(8192)  # read in chunks to avoid memory errors for large files

            if not chunk:
                break

            digest.update(chunk)

    return digest.hexdigest()
```
