import random
from math import gcd

def generate_prime():

    while True:
        num = random.getrandbits(512)  
        num |= 2 ** 512 + 1           
        if all(num % p != 0 for p in range(3, int(num**0.5) + 1, 2)):
            return num

def generate_rsa_key_pair(prime_length=512):

    p = q = None
    while not p or not q:
        p = generate_prime()
        q = generate_prime()

    n = p * q
    phi_n = (p - 1) * (q - 1)

    while True:
        e = random.randint(65537, phi_n - 1) if phi_n > 65537 else random.randint(3, phi_n - 1)
        if gcd(e, phi_n) == 1:
            break

    d = pow(e, -1, phi_n)

    return n, e, d

def main():
    num_keys = int(input(""Enter the number of RSA key pairs to generate: ""))

    for _ in range(num_keys):
        keys = generate_rsa_key_pair()
        print(f""RSA Key Pair {(_ + 1)}: {keys}"")

if __name__ == ""__main__"":
    main()
```
