```python
import hashlib

def sha256_hash(file_path):
    hash_obj = hashlib.sha256()
    with open(file_path, 'rb') as f:
        while True:
            chunk = f.read(4096)  # Read file in chunks of 4KB
            if not chunk:
                break
            hash_obj.update(chunk)
    return hash_obj.hexdigest()
```
