class TestCreateOctreeCompressedArchives(unittest.TestCase):
    def setUp(self):
        self.filename = ""testfile""

    def tearDown(self):
        for file in os.listdir():
            if self.filename in file:
                os.remove(file)

    def test_valid_input(self):
        create_octree_compressed_archives(5, self.filename, 3)

