def generate_random_password(length, uppercase=False, lowercase=True, digits=True, special_chars=False):
    characters = ''

    if uppercase:
        characters += string.ascii_uppercase

    if lowercase:
        characters += string.ascii_lowercase

    if digits:
        characters += string.digits

    if special_chars:
        characters += string.punctuation

    return ''.join(random.choice(characters) for _ in range(length))

def create_cipher(password):
    password = password.encode('utf-8')  # convert to bytes
    libc.create_cipher(password, len(password))
