class KeyVault:
    def __init__(self):
        self.keys = []

    def generate_secure_key(self) -> bytes:
        return os.urandom(32)

    def generate_unique_key_id(self) -> str:
        while True:
            unique_id = hashlib.sha256(os.urandom(64)).hexdigest()
            if not self.is_duplicate(unique_id):
                return unique_id

    def is_duplicate(self, key_id: str) -> bool:
        return any(key.key_id == key_id for key in self.keys)

    def encrypt_key(self, plain_text: bytes, password: str) -> bytes:
        salt = os.urandom(16)
        kdf = PBKDF2HMAC(
            algorithm=hashes.SHA256(),
            length=32,
            salt=salt,
            iterations=100000,
        )
        derived_key = kdf.derive(password.encode())

        cipher = Cipher(algorithms.AES(derived_key), modes.CBC(salt))

        encryptor = cipher.encryptor()

        padded_plaintext = plain_text + b'\x04' * (16 - len(plain_text) % 16)

        ciphertext = encryptor.update(padded_plaintext) + encryptor.finalize()

        return salt + ciphertext

